const message = $json.message?.text || $json.text || '';
const chatId = $json.message?.chat?.id || $json.chat_id || null;
const userId = $json.message?.from?.id || $json.user_id || null;
if (!chatId) throw new Error('Telegram chat.id is required');
return [{ json: { raw_message: message, telegram_chat_id: String(chatId), telegram_user_id: userId ? String(userId) : null, correlation_id: crypto.randomUUID() } }];

const text = ($json.raw_message || '').trim().toLowerCase();
const approvals = new Set(['setuju','iya','ya','oke','ok','gas','lanjut','buat','sudah benar','sip']);
let intent = 'UNKNOWN';
if (approvals.has(text)) intent = 'APPROVE_DRAFT';
else if (/kirim.*ulang|kirim.*lagi|resend/.test(text)) intent = 'RESEND_INVOICE';
else if (/status|sudah terkirim|invoice .* mana/.test(text)) intent = 'GET_STATUS';
else if (/ganti|ubah|revisi|jadi|tidak usah dp/.test(text) || (/tanpa dp/.test(text) && !/buat|invoice|tagihan/.test(text))) intent = 'UPDATE_DRAFT';
else if (/invoice|tagihan/.test(text)) intent = 'CREATE_INVOICE';
return [{ json: { ...$json, intent, confidence: intent === 'UNKNOWN' ? 0.2 : 0.7, intent_source: 'deterministic_prefilter' } }];
